            t0 = Model.NodeTextStart(on, c);
            t1 = Model.NodeTextStart(on, c) + Model.NodeTextLen(on, c);
            if ((act != 1) && (act != 2)) {
                RsCloseAll(nodes, regions, stk, @base);
            }
            // an item: into a list, nested or not
            if (act == 1) {
                ls = RsPlaceItem(on, oa, orr, nodes, attrs, regions, text, stk, lay, @base, c, np);
                f = @base + ((RsDepth(stk, @base) - 1) * RsFr);
                nn = RsNode(on, oa, orr, nodes, attrs, regions, nm, c, ls);
                Model.NodeSetSub(nodes, nn, 0);
                Model.NodeSetAux(nodes, nn, 0);
                // no frame: the Model's depth limit stopped the list; the item stands where it is
                if (RsDepth(stk, @base) >= 1) {
                    if ((emon.Port.CellsAt(stk, f + 2) != 1) && (Model.NodeAux(on, c) > 0) && (emon.Port.CellsAt(stk, f + 4) != -1) && (Model.NodeAux(on, c) != (emon.Port.CellsAt(stk, f + 3) + 1))) {
                        Model.NodeSetAttrInt(nodes, attrs, nn, Model.FkValue(), Model.NodeAux(on, c));
                    }
                    emon.Port.CellsSet(stk, f + 3, Model.NodeAux(on, c));
                    emon.Port.CellsSet(stk, f + 4, nn);
                }
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, c, nn);
            }
            // a milestone or a note inside a list that goes on: kept in the item before it
            if (act == 2) {
                f = @base + ((RsDepth(stk, @base) - 1) * RsFr);
                hold = emon.Port.CellsAt(stk, f + 4);
                if (hold < 0) {
                    hold = np;
                }
                nn = RsNode(on, oa, orr, nodes, attrs, regions, nm, c, hold);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, c, nn);
            }
            // the caption above its object
            if (act == 3) {
                q = Model.NodeNext(on, c);
                nn = RsNode(on, oa, orr, nodes, attrs, regions, nm, q, np);
                cn = RsNode(on, oa, orr, nodes, attrs, regions, nm, c, nn);
                RsPair(@out, cn, nn);
                RsLabelOf(on, oa, c, nodes, attrs, nn);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, c, cn);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, q, nn);
                c = q;
            }
            // a figure caption with no figure: the evidence of a figure nothing else found
            if (act == 4) {
                nn = Model.NodeNew(nodes, Model.NkFigure(), np);
                Model.NodeSetSub(nodes, nn, Model.FgUnknown());
                Model.NodeSetConf(nodes, nn, 500);
                Model.NodeAddSrc(nodes, nn, Model.SrInfer());
                RsCopyRegions(on, orr, nodes, regions, c, nn);
                RsLabelOf(on, oa, c, nodes, attrs, nn);
                cn = RsNode(on, oa, orr, nodes, attrs, regions, nm, c, nn);
                RsPair(@out, cn, nn);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, c, cn);
            }
            // an object and the caption below it
            if (act == 5) {
                q = Model.NodeNext(on, c);
                nn = RsNode(on, oa, orr, nodes, attrs, regions, nm, c, np);
                cn = RsNode(on, oa, orr, nodes, attrs, regions, nm, q, nn);
                RsPair(@out, cn, nn);
                RsLabelOf(on, oa, q, nodes, attrs, nn);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, q, cn);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, c, nn);
                c = q;
            }
            if (act == 6) {
                RsPieces(nodes, attrs, text, np, t0, t1, @out);
            }
            if ((act == 7) || (act == 8)) {
                nn = RsNode(on, oa, orr, nodes, attrs, regions, nm, c, np);
                if (act == 8) {
                    Model.NodeSetText(nodes, nn, -1, 0);
                    RsPieces(nodes, attrs, text, nn, t0, t1, @out);
                } else {
                    RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, c, nn);
                }
            }
            c = Model.NodeNext(on, c);
        }
        RsCloseAll(nodes, regions, stk, @base);
        return 0;
    }
    public static int RsRemap(emon.Port.Cells attrs, emon.Port.Cells nm) {
        // Node-valued attributes point at old nodes: point them at the new ones.
        int a = 0;
        int n = emon.Port.CellsLen(attrs) / 5;
        while (a < n) {
            if (emon.Port.CellsAt(attrs, (a * 5) + 1) == Model.AvNode()) {
                int v = emon.Port.CellsAt(attrs, (a * 5) + 2);
                if ((v >= 0) && (v < emon.Port.CellsLen(nm))) {
                    emon.Port.CellsSet(attrs, (a * 5) + 2, emon.Port.CellsAt(nm, v));
                }
            }
            a += 1;
        }
        return 0;
    }
    internal static bool RsSameRun(emon.Port.Cells text, int s1, int l1, int s2, int l2) {
        if (l1 != l2) {
            return 0 == 1;
        }
        int i = 0;
        while (i < l1) {
            if (emon.Port.CellsAt(text, s1 + i) != emon.Port.CellsAt(text, s2 + i)) {
                return 0 == 1;
            }
            i += 1;
        }
        return 1 == 1;
    }
    internal static int RsScan(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells used, int from, int to, int ma) {
        // The first unclaimed note of `used`[from, to) whose marker is the attribute `ma`'s: its index there, or -1.
        int j = from;
        while (j < to) {
            if (emon.Port.CellsAt(used, (j * 2) + 1) == 0) {
                int na = Model.NodeAttr(nodes, attrs, emon.Port.CellsAt(used, j * 2), Model.FkMarker());
                if ((na >= 0) && RsSameRun(text, Model.AttrValue(attrs, ma), Model.AttrLen(attrs, ma), Model.AttrValue(attrs, na), Model.AttrLen(attrs, na))) {
                    return j;
                }
            }
            j += 1;
        }
        return -1;
    }
    internal static int RsLinkRefs(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells used) {
        // Give each `ref` the `target` of the next note body with its marker that is not claimed: forward from the
        // reference, then from the start. `used` is scratch: a note's node and whether it is taken.
        int cnt = Model.NodeCount(nodes);
        int i = 0;
        int nn = 0;
        int p0 = 0;
        int ma = -1;
        int found = -1;
        emon.Port.CellsDrop(used, 0);
        while (i < cnt) {
            if (Model.NodeKind(nodes, i) == Model.NkNote()) {
                emon.Port.CellsPush(used, i);
                emon.Port.CellsPush(used, 0);
                nn += 1;
            }
            i += 1;
        }
        if (nn == 0) {
            return 0;
        }
        i = 0;
        while (i < cnt) {
            if (Model.NodeKind(nodes, i) == Model.NkRef()) {
                ma = Model.NodeAttr(nodes, attrs, i, Model.FkMarker());
                if ((ma >= 0) && (Model.NodeAttr(nodes, attrs, i, Model.FkTarget()) < 0)) {
                    while ((p0 < nn) && (emon.Port.CellsAt(used, p0 * 2) < i)) {
                        p0 += 1;
                    }
                    found = RsScan(nodes, attrs, text, used, p0, nn, ma);
                    if (found < 0) {
                        found = RsScan(nodes, attrs, text, used, 0, p0, ma);
                    }
                    if (found >= 0) {
                        emon.Port.CellsSet(used, (found * 2) + 1, 1);
                        Model.NodeSetAttrNode(nodes, attrs, i, Model.FkTarget(), emon.Port.CellsAt(used, found * 2));
                    }
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int RsScrubText(emon.Port.Cells text) {
        // A last safety: no Unicode noncharacter (U+FDD0..U+FDEF: what the groups of `emon.lists` are made of) is in the
        // Model's text, whoever wrote it (a table's cell is written from the words, and a word of one that the stages here
        // rewrote would have carried a group into it): U+FFFD stands for it, where it can be seen.
        int i = 0;
        while (i < emon.Port.CellsLen(text)) {
            int c = emon.Port.CellsAt(text, i);
            if ((c >= 64976) && (c <= 65007)) {
                emon.Port.CellsSet(text, i, 65533);
            }
            i += 1;
        }
        return 0;
    }
    internal static bool RsDestKind(int k) {
        // The blocks a link can name: what a reader would call the place a destination is.
        return (k == Model.NkHeading()) || ((k == Model.NkParagraph()) || ((k == Model.NkItem()) || ((k == Model.NkCaption()) || ((k == Model.NkFigure()) || ((k == Model.NkTable()) || ((k == Model.NkNote()) || (k == Model.NkQuote())))))));
    }
    internal static int RsDestBuild(emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells used) {
        // `used`: a row of six for each region of each block a link can name (`rs-dest-kind`): the node, its page, its box.
        int cnt = Model.NodeCount(nodes);
        int i = 0;
        int r = 0;
        emon.Port.CellsDrop(used, 0);
        while (i < cnt) {
            if (RsDestKind(Model.NodeKind(nodes, i))) {
                r = Model.NodeRegionHead(nodes, i);
                while (r >= 0) {
                    emon.Port.CellsPush(used, i);
                    emon.Port.CellsPush(used, Model.RegionPage(regions, r));
                    emon.Port.CellsPush(used, Model.RegionX0(regions, r));
                    emon.Port.CellsPush(used, Model.RegionY0(regions, r));
                    emon.Port.CellsPush(used, Model.RegionX1(regions, r));
                    emon.Port.CellsPush(used, Model.RegionY1(regions, r));
                    r = Model.RegionNext(regions, r);
                }
            }
            i += 1;
        }
        return emon.Port.CellsLen(used) / 6;
    }
    internal static int RsXdist(int x0, int x1, int x) {
        // How far x is outside [x0, x1]: 0 inside.
        if (x < x0) {
            return x0 - x;
        }
        if (x > x1) {
            return x - x1;
        }
        return 0;
    }
    internal static int RsDestFind(emon.Port.Cells used, int page, int y, int x, int mode) {
        // The block a destination names (P4.7, D193): of the blocks on `page` that do not end above the point (3 pt of
        // slack: a destination is set a little above its heading, a paragraph that ends there is not it), the topmost; a
        // destination with no y has no top to be under. The point's x tells the column: mode 0 takes only the blocks whose
        // extent is within 6 pt of it (a destination is at its entry's left edge or a little outside it, and the gutter is
        // wider), mode 1 within 20 pt, mode 2 without the x; mode 3 the topmost block of the first page at or after `page`
        // that has one. -1 when none.
        int n = emon.Port.CellsLen(used) / 6;
        int j = 0;
        int best = -1;
        int bp = 0;
        int by = 0;
        int tol = 2000;
        if (mode == 0) {
            tol = 600;
        }
        while (j < n) {
            int b = j * 6;
            int p = emon.Port.CellsAt(used, b + 1);
            int y0 = emon.Port.CellsAt(used, b + 3);
            if ((mode < 3) && (p == page)) {
                if ((y < 0) || (emon.Port.CellsAt(used, b + 5) > (y + 300))) {
                    if ((mode == 2) || (x < 0) || (RsXdist(emon.Port.CellsAt(used, b + 2), emon.Port.CellsAt(used, b + 4), x) <= tol)) {
                        if ((best < 0) || (y0 < by)) {
                            best = emon.Port.CellsAt(used, b);
                            by = y0;
                        }
                    }
                }
            }
            if ((mode == 3) && (p >= page)) {
                if ((best < 0) || (p < bp) || ((p == bp) && (y0 < by))) {
                    best = emon.Port.CellsAt(used, b);
                    bp = p;
                    by = y0;
                }
            }
            j += 1;
        }
        return best;
    }
    internal static int RsResolveLinks(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells used) {
        // Every internal link (`sub` the destination's page + 1, `aux` its point as `emon.inline` packed it) gets the
        // `target` of the block it names and its `sub` and `aux` back to 0. The work is bounded (50 million rows looked at):
        // a link past it keeps no target.
        int cnt = Model.NodeCount(nodes);
        int rows = RsDestBuild(nodes, regions, used);
        int i = 0;
        int tg = -1;
        int work = 0;
        int ys = 0;
        int xs = 0;
        int y = -1;
        int x = -1;
        while (i < cnt) {
            if ((Model.NodeKind(nodes, i) == Model.NkLink()) && (Model.NodeSub(nodes, i) > 0)) {
                ys = Model.NodeAux(nodes, i) / 32768;
                xs = Model.NodeAux(nodes, i) % 32768;
                y = -1;
                x = -1;
                if (ys > 0) {
                    y = (ys - 1) * 100;
                }
                if (xs > 0) {
                    x = (xs - 1) * 100;
                }
                tg = -1;
                if (work < 50000000) {
                    tg = RsDestFind(used, Model.NodeSub(nodes, i), y, x, 0);
                    if (tg < 0) {
                        tg = RsDestFind(used, Model.NodeSub(nodes, i), y, x, 1);
                    }
                    if (tg < 0) {
                        tg = RsDestFind(used, Model.NodeSub(nodes, i), y, x, 2);
                    }
                    if (tg < 0) {
                        tg = RsDestFind(used, Model.NodeSub(nodes, i), y, x, 3);
                    }
                    work += 4 * rows;
                }
                if (tg >= 0) {
                    Model.NodeSetAttrNode(nodes, attrs, i, Model.FkTarget(), tg);
                }
                Model.NodeSetSub(nodes, i, 0);
                Model.NodeSetAux(nodes, i, 0);
            }
            i += 1;
        }
        return 0;
    }
    public static int RsRun(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells nm, emon.Port.Cells stk, emon.Port.Cells used, emon.Port.Cells @out, emon.Port.Cells lay) {
        // Copy the old Model's trees, restructured, into the empty arenas `nodes`, `attrs`, `regions` (see the head).
        // `nm` (old node to new), `stk` (the list frames), `used` and `out` (three cells) are scratch. Answers the new
        // node count.
        int n = Model.NodeCount(on);
        int r = 0;
        int i = 0;
        emon.Port.CellsDrop(nodes, 0);
        emon.Port.CellsDrop(attrs, 0);
        emon.Port.CellsDrop(regions, 0);
        emon.Port.CellsDrop(nm, 0);
        emon.Port.CellsDrop(stk, 0);
        emon.Port.CellsDrop(@out, 0);
        emon.Port.CellsPush(@out, 0);
        emon.Port.CellsPush(@out, 0);
        emon.Port.CellsPush(@out, 0);
        while (i < n) {
            emon.Port.CellsPush(nm, -1);
            i += 1;
        }
        while (r < n) {
            if (Model.NodeParent(on, r) < 0) {
                int nr = RsNode(on, oa, orr, nodes, attrs, regions, nm, r, -1);
                RsChildren(on, oa, orr, text, nodes, attrs, regions, nm, stk, @out, lay, r, nr);
            }
            r += 1;
        }
        RsRemap(attrs, nm);
        RsTargets(nodes, attrs, @out);
        RsLinkRefs(nodes, attrs, text, used);
        RsResolveLinks(nodes, attrs, regions, used);
        RsScrubText(text);
        return Model.NodeCount(nodes);
    }
    internal static int RfNode(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells nm, int n, int np, int caption) {
        // `rs-node`, but every attribute is kept (the item's private `fk-box` too: `rs-run` reads it).
        int kind = Model.NodeKind(on, n);
        if (caption == 1) {
            kind = Model.NkCaption();
        }
        int nn = Model.NodeNew(nodes, kind, np);
        if (nn < 0) {
            nn = Model.NodeNew(nodes, kind, 0);
        }
        if (nn < 0) {
            return -1;
        }
        Model.NodeSetSub(nodes, nn, Model.NodeSub(on, n));
        Model.NodeSetAux(nodes, nn, Model.NodeAux(on, n));
        if (caption == 1) {
            Model.NodeSetAux(nodes, nn, 1);
            Model.NodeSetSub(nodes, nn, 0);
        }
        Model.NodeSetSrc(nodes, nn, Model.NodeSrc(on, n));
        Model.NodeSetConf(nodes, nn, Model.NodeConf(on, n));
        Model.NodeSetFlags(nodes, nn, Model.NodeFlags(on, n));
        if (Model.NodeHasText(on, n) == 1) {
            Model.NodeSetText(nodes, nn, Model.NodeTextStart(on, n), Model.NodeTextLen(on, n));
        }
        int a = Model.NodeAttrHead(on, n);
        while (a >= 0) {
            int k = Model.AttrKey(oa, a);
            int vk = Model.AttrVkind(oa, a);
            int v = Model.AttrValue(oa, a);
            int l = Model.AttrLen(oa, a);
            if (caption == 1) {
                if (k == Model.FkNumber()) {
                    k = Model.FkLabel();
                }
                if (k == Model.FkNumbering()) {
                    k = -1;
                }
            }
            if ((k >= 0) && (vk == Model.AvText())) {
                Model.NodeAddAttrText(nodes, attrs, nn, k, v, l);
            }
            if (vk == Model.AvInt()) {
                Model.NodeAddAttrInt(nodes, attrs, nn, k, v);
            }
            if (vk == Model.AvNode()) {
                Model.NodeSetAttrNode(nodes, attrs, nn, k, v);
            }
            if (vk == Model.AvBool()) {
                Model.NodeSetAttrBool(nodes, attrs, nn, k, v);
            }
            a = Model.AttrNext(oa, a);
        }
        int r = Model.NodeRegionHead(on, n);
        while (r >= 0) {
            Model.NodeAddRegion(nodes, regions, nn, Model.RegionPage(orr, r), Model.RegionX0(orr, r), Model.RegionY0(orr, r), Model.RegionX1(orr, r), Model.RegionY1(orr, r));
            r = Model.RegionNext(orr, r);
        }
        emon.Port.CellsSet(nm, n, nn);
        return nn;
    }
    internal static int RfRegion(emon.Port.Cells on, int c) {
        // The first region row of node c, or of its first descendant that has one; -1 when there is none.
        int r = Model.NodeRegionHead(on, c);
        int q = Model.NodeFirstChild(on, c);
        int found = -1;
        if (r >= 0) {
            return r;
        }
        while ((q >= 0) && (found < 0)) {
            found = RfRegion(on, q);
            q = Model.NodeNext(on, q);
        }
        return found;
    }
    internal static int RfNextRegion(emon.Port.Cells on, int c) {
        // The first region row of a sibling after c (or of what is in it); -1 when none has one.
        int q = Model.NodeNext(on, c);
        int r = -1;
        while ((q >= 0) && (r < 0)) {
            r = RfRegion(on, q);
            q = Model.NodeNext(on, q);
        }
        return r;
    }
    internal const int RfFd = 8;
    internal const int RfCapgap = 4000;
    internal static int RfMin(int a, int b) {
        if (a < b) {
            return a;
        }
        return b;
    }
    internal static int RfMax(int a, int b) {
        if (a > b) {
            return a;
        }
        return b;
    }
    internal const int RfZone = 2400;
    internal const int RfLabelH = 1800;
    internal const int RfLabelCp = 48;
    internal const int RfLabelWords = 6;
    internal const int RfPasses = 3;
    internal const int RfInsideH = 4500;
    internal const int RfInsideCp = 120;
    internal const int RfInsideBig = 50000;
    internal static int RfFdv(emon.Port.Cells fd, int row, int f, int dflt) {
        if (emon.Port.CellsLen(fd) < ((row + 1) * RfFd)) {
            return dflt;
        }
        return emon.Port.CellsAt(fd, (row * RfFd) + f);
    }
    internal static bool RfLabelText(emon.Port.Cells on, emon.Port.Cells text, int p) {
        // A paragraph's text that a label can be: few code points and words, not a sentence (no final full stop).
        int s = Model.NodeTextStart(on, p);
        int l = Model.NodeTextLen(on, p);
        int i = 0;
        int words = 1;
        if ((l < 1) || (l > RfLabelCp)) {
            return 0 == 1;
        }
        if (emon.Port.CellsAt(text, s + (l - 1)) == 46) {
            return 0 == 1;
        }
        while (i < l) {
            if (emon.Port.CellsAt(text, s + i) == 32) {
                words += 1;
            }
            i += 1;
        }
        return words <= RfLabelWords;
    }
    internal static int RfEb(emon.Port.Cells ab, int n, int k, emon.Port.Cells cand, int row, int f) {
        // Coordinate f (0 x0, 1 y0, 2 x1, 3 y1) of the box the labels of the figure number `k` of `fg` (1 based) are looked for in: its own, grown over the labels near it (`rf-grow`, kept in `ab` after
        // the node entries, four cells a figure), else its candidate row's.
        if (emon.Port.CellsLen(ab) >= (n + (4 * k))) {
            return emon.Port.CellsAt(ab, n + ((4 * (k - 1)) + f));
        }
        return Asset.AsGet(cand, row, 5 + f);
    }
    internal static int RfLabelOf(emon.Port.Cells on, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab, int n, int p) {
        // The candidate row of the figure that paragraph p labels, or -1. A label is a short one-line paragraph on the figure or within `RF_ZONE` of its box, as grown over the labels around it
        // (`rf-grow`); inside the figure's own box (a figure no taller than `RF_INSIDE_BIG`) any paragraph of at most three lines and `RF_INSIDE_CP` characters is: the text of a figure is its labels (D583).
        int r = Model.NodeRegionHead(on, p);
        int i = 1;
        int row = 0;
        int cx = 0;
        int cy = 0;
        int hgt = 0;
        if (r < 0) {
            return -1;
        }
        if (Model.NodeRegionCount(on, p) != 1) {
            return -1;
        }
        if (Model.NodeHasText(on, p) == 0) {
            return -1;
        }
        hgt = Model.RegionY1(orr, r) - Model.RegionY0(orr, r);
        cx = (Model.RegionX0(orr, r) + Model.RegionX1(orr, r)) / 2;
        cy = (Model.RegionY0(orr, r) + Model.RegionY1(orr, r)) / 2;
        while (i < emon.Port.CellsLen(fg)) {
            row = emon.Port.CellsAt(fg, i);
            if ((Asset.AsGet(cand, row, 0) == Model.RegionPage(orr, r)) && ((cx >= Asset.AsGet(cand, row, 5)) && ((cx <= Asset.AsGet(cand, row, 7)) && ((cy >= Asset.AsGet(cand, row, 6)) && ((cy <= Asset.AsGet(cand, row, 8)) && (((Asset.AsGet(cand, row, 8) - Asset.AsGet(cand, row, 6)) <= RfInsideBig) && ((hgt <= RfInsideH) && (Model.NodeTextLen(on, p) <= RfInsideCp)))))))) {
                return row;
            }
            i += 1;
        }
        if (hgt > RfLabelH) {
            return -1;
        }
        if (!RfLabelText(on, text, p)) {
            return -1;
        }
        i = 1;
        while (i < emon.Port.CellsLen(fg)) {
            row = emon.Port.CellsAt(fg, i);
            if ((Asset.AsGet(cand, row, 0) == Model.RegionPage(orr, r)) && ((Model.RegionX1(orr, r) > (RfEb(ab, n, i, cand, row, 0) - RfZone)) && ((Model.RegionX0(orr, r) < (RfEb(ab, n, i, cand, row, 2) + RfZone)) && ((cy >= (RfEb(ab, n, i, cand, row, 1) - RfZone)) && ((cy <= (RfEb(ab, n, i, cand, row, 3) + RfZone)) && ((Model.RegionX1(orr, r) - Model.RegionX0(orr, r)) <= ((2 * (RfEb(ab, n, i, cand, row, 2) - RfEb(ab, n, i, cand, row, 0))) + 2000))))))) {
                return row;
            }
            i += 1;
        }
        return -1;
    }
    internal static int RfGrows(emon.Port.Cells fd, int row) {
        // 1 when the figure of candidate row `row` may grow over its labels: a drawing, a chart, a picture; not a logo, a barcode or a code (a name, a number beside them is text).
        int k = RfFdv(fd, row, 0, Model.FgUnknown());
        if ((k == Model.FgLogo()) || ((k == Model.FgBarcode()) || (k == Model.FgQr()))) {
            return 0;
        }
        return 1;
    }
    internal static int RfGrow(emon.Port.Cells on, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab, int n) {
        // D583 (smoke review B issue 7): the boxes the labels of each figure are looked for in, kept in `ab` after its `n` node entries (four cells a figure of `fg`, in its order): each is the
        // figure's candidate box grown, in `RF_PASSES` passes, over the label-like paragraphs (one line, a few words, `rf-label-text`) within `RF_ZONE` of it: a drawing's boxes are separate regions of
        // paths and words, and the words between and beside them are its labels too. Answers how many paragraphs it took in.
        int i = 1;
        int row = 0;
        int pass = 0;
        int c = 0;
        int r = 0;
        int took = 0;
        int b = 0;
        int changed = 1;
        int cy = 0;
        while (i < emon.Port.CellsLen(fg)) {
            row = emon.Port.CellsAt(fg, i);
            emon.Port.CellsPush(ab, Asset.AsGet(cand, row, 5));
            emon.Port.CellsPush(ab, Asset.AsGet(cand, row, 6));
            emon.Port.CellsPush(ab, Asset.AsGet(cand, row, 7));
            emon.Port.CellsPush(ab, Asset.AsGet(cand, row, 8));
            i += 1;
        }
        while ((pass < RfPasses) && (changed == 1)) {
            changed = 0;
            c = 0;
            while (c < n) {
                if (Model.NodeKind(on, c) == Model.NkParagraph()) {
                    r = Model.NodeRegionHead(on, c);
                    if ((r >= 0) && ((Model.NodeRegionCount(on, c) == 1) && ((Model.NodeHasText(on, c) == 1) && (((Model.RegionY1(orr, r) - Model.RegionY0(orr, r)) <= RfLabelH) && RfLabelText(on, text, c))))) {
                        cy = (Model.RegionY0(orr, r) + Model.RegionY1(orr, r)) / 2;
                        i = 1;
                        while (i < emon.Port.CellsLen(fg)) {
                            row = emon.Port.CellsAt(fg, i);
                            b = n + (4 * (i - 1));
                            if ((RfGrows(fd, row) == 1) && ((Asset.AsGet(cand, row, 0) == Model.RegionPage(orr, r)) && ((Model.RegionX1(orr, r) > (emon.Port.CellsAt(ab, b) - RfZone)) && ((Model.RegionX0(orr, r) < (emon.Port.CellsAt(ab, b + 2) + RfZone)) && ((cy >= (emon.Port.CellsAt(ab, b + 1) - RfZone)) && (cy <= (emon.Port.CellsAt(ab, b + 3) + RfZone))))))) {
                                if (Model.RegionX0(orr, r) < emon.Port.CellsAt(ab, b)) {
                                    emon.Port.CellsSet(ab, b, Model.RegionX0(orr, r));
                                    changed = 1;
                                }
                                if (Model.RegionY0(orr, r) < emon.Port.CellsAt(ab, b + 1)) {
                                    emon.Port.CellsSet(ab, b + 1, Model.RegionY0(orr, r));
                                    changed = 1;
                                }
                                if (Model.RegionX1(orr, r) > emon.Port.CellsAt(ab, b + 2)) {
                                    emon.Port.CellsSet(ab, b + 2, Model.RegionX1(orr, r));
                                    changed = 1;
                                }
                                if (Model.RegionY1(orr, r) > emon.Port.CellsAt(ab, b + 3)) {
                                    emon.Port.CellsSet(ab, b + 3, Model.RegionY1(orr, r));
                                    changed = 1;
                                }
                                took += 1;
                            }
                            i += 1;
                        }
                    }
                }
                c += 1;
            }
            pass += 1;
        }
        return took;
    }
    internal static int RfAbsorbNote(emon.Port.Cells on, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab, int n) {
        // A note (the column stage made a margin note of a column of tick labels) every child of which is a label of one figure is
        // dropped with them: the note and its paragraphs are marked.
        int c = Model.NodeFirstChild(on, n);
        int nall = Model.NodeCount(on);
        int f = -1;
        int g = 0;
        int ok = 1;
        int cnt = 0;
        while (c >= 0) {
            g = -1;
            if (Model.NodeKind(on, c) == Model.NkParagraph()) {
                g = RfLabelOf(on, orr, text, cand, fg, fd, ab, nall, c);
            }
            if (g < 0) {
                ok = 0;
            }
            if ((g >= 0) && ((f >= 0) && (g != f))) {
                ok = 0;
            }
            if (g >= 0) {
                f = g;
            }
            cnt += 1;
            c = Model.NodeNext(on, c);
        }
        if ((ok == 1) && (cnt > 0)) {
            emon.Port.CellsSet(ab, n, f);
            c = Model.NodeFirstChild(on, n);
            while (c >= 0) {
                emon.Port.CellsSet(ab, c, f);
                c = Model.NodeNext(on, c);
            }
        }
        return 0;
    }
    internal static int RfMarkGrid(emon.Port.Cells on, emon.Port.Cells ab, int n, int row) {
        int c = Model.NodeFirstChild(on, n);
        emon.Port.CellsSet(ab, n, row);
        while (c >= 0) {
            RfMarkGrid(on, ab, c, row);
            c = Model.NodeNext(on, c);
        }
        return 0;
    }
    internal static int RfGridOwner(emon.Port.Cells on, emon.Port.Cells orr, emon.Port.Cells cand, emon.Port.Cells fg, int n) {
        int r = Model.NodeRegionHead(on, n);
        int i = 1;
        int row = 0;
        if ((r < 0) || (Model.NodeRegionCount(on, n) != 1)) {
            return -1;
        }
        if (RsHasCaption(on, n)) {
            return -1;
        }
        while (i < emon.Port.CellsLen(fg)) {
            row = emon.Port.CellsAt(fg, i);
            if ((Asset.AsGet(cand, row, 30) == 5) && ((Model.RegionPage(orr, r) == Asset.AsGet(cand, row, 0)) && ((Model.RegionX0(orr, r) >= Asset.AsGet(cand, row, 5)) && ((Model.RegionY0(orr, r) >= Asset.AsGet(cand, row, 6)) && ((Model.RegionX1(orr, r) <= Asset.AsGet(cand, row, 7)) && (Model.RegionY1(orr, r) <= Asset.AsGet(cand, row, 8))))))) {
                return row;
            }
            i += 1;
        }
        return -1;
    }
    internal static int RfAbsorb(emon.Port.Cells on, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab, int p) {
        // Mark, among the blocks of p (the document or a section) and of the sections in it, the paragraphs that label a figure.
        int c = Model.NodeFirstChild(on, p);
        int nall = Model.NodeCount(on);
        int f = -1;
        while (c >= 0) {
            if (Model.NodeKind(on, c) == Model.NkSection()) {
                RfAbsorb(on, orr, text, cand, fg, fd, ab, c);
            }
            if (Model.NodeKind(on, c) == Model.NkNote()) {
                RfAbsorbNote(on, orr, text, cand, fg, fd, ab, c);
            }
            if (Model.NodeKind(on, c) == Model.NkTable()) {
                f = RfGridOwner(on, orr, cand, fg, c);
                if (f >= 0) {
                    RfMarkGrid(on, ab, c, f);
                }
            }
            if (Model.NodeKind(on, c) == Model.NkParagraph()) {
                f = RfLabelOf(on, orr, text, cand, fg, fd, ab, nall, c);
                if (f >= 0) {
                    emon.Port.CellsSet(ab, c, f);
                }
            }
            c = Model.NodeNext(on, c);
        }
        return 0;
    }
    internal static int RfLabels(emon.Port.Cells on, emon.Port.Cells ab, emon.Port.Cells nodes, emon.Port.Cells attrs, int nn, int row) {
        // The texts of the paragraphs marked as labels of the figure `row`, in node order, as `labels` of the new figure nn.
        int n = Model.NodeCount(on);
        int c = 0;
        while (c < n) {
            if ((emon.Port.CellsAt(ab, c) == row) && ((Model.NodeKind(on, c) == Model.NkParagraph()) || ((Model.NodeKind(on, c) == Model.NkCell()) && (Model.NodeHasText(on, c) == 1)))) {
                Model.NodeAddAttrText(nodes, attrs, nn, Model.FkLabels(), Model.NodeTextStart(on, c), Model.NodeTextLen(on, c));
            }
            c += 1;
        }
        return 0;
    }
    internal static int RfMake(emon.Port.Cells on, emon.Port.Cells ab, emon.Port.Cells cand, emon.Port.Cells fd, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, int np, int row) {
        // The figure node of candidate row `row` as the last child of np: its kind, confidence, sources, region, asset row and labels.
        int nn = Model.NodeNew(nodes, Model.NkFigure(), np);
        int link = 0;
        if (nn >= 0) {
            Model.NodeSetSub(nodes, nn, RfFdv(fd, row, 0, Model.FgUnknown()));
            Model.NodeSetConf(nodes, nn, RfFdv(fd, row, 1, 500));
            Model.NodeAddSrc(nodes, nn, RfFdv(fd, row, 2, 0) | Model.SrInfer());
            Model.NodeAddRegion(nodes, regions, nn, Asset.AsGet(cand, row, 0), Asset.AsGet(cand, row, 5), Asset.AsGet(cand, row, 6), Asset.AsGet(cand, row, 7), Asset.AsGet(cand, row, 8));
            link = RfFdv(fd, row, 3, row);
            if (link >= 0) {
                Model.NodeSetAttrInt(nodes, attrs, nn, Model.FkImage(), link);
            }
            if (emon.Port.CellsLen(fd) > 0) {
                RfLabels(on, ab, nodes, attrs, nn, row);
            }
        }
        return nn;
    }
    internal static int RfFlush(emon.Port.Cells on, emon.Port.Cells ab, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, int np, int lpage, int ly) {
        // Make the pending figures whose top edge is before the position (lpage, ly) as children of np; lpage -1 is no
        // limit. `fg`[0] is the cursor.
        int cur = emon.Port.CellsAt(fg, 0);
        int row = 0;
        int more = 1;
        while ((more == 1) && ((cur + 1) < emon.Port.CellsLen(fg))) {
            row = emon.Port.CellsAt(fg, cur + 1);
            more = 0;
            if (lpage < 0) {
                more = 1;
            }
            if ((lpage >= 0) && (Asset.AsGet(cand, row, 0) < lpage)) {
                more = 1;
            }
            if ((lpage >= 0) && ((Asset.AsGet(cand, row, 0) == lpage) && (Asset.AsGet(cand, row, 6) < ly))) {
                more = 1;
            }
            if (more == 1) {
                RfMake(on, ab, cand, fd, nodes, attrs, regions, np, row);
                cur += 1;
                emon.Port.CellsSet(fg, 0, cur);
            }
        }
        return 0;
    }
    internal static int RfFlushAnchor(emon.Port.Cells on, emon.Port.Cells ab, emon.Port.Cells cand, emon.Port.Cells fd, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, int np, int cpn) {
        // Make the figures whose caption is the old node `cpn` (`fd` cell 4), just before it: a figure belongs with its caption, whatever
        // column it stands in.
        int rows = emon.Port.CellsLen(fd) / RfFd;
        int row = 0;
        while (row < rows) {
            if (emon.Port.CellsAt(fd, (row * RfFd) + 4) == cpn) {
                RfMake(on, ab, cand, fd, nodes, attrs, regions, np, row);
            }
            row += 1;
        }
        return 0;
    }
    internal static int RfAnchor(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd) {
        // Each figure that has a figure caption (`caption`, kind 1) among the blocks of the document or a section just below it, within
        // `RF_CAPGAP`, and overlapping it in x, is anchored to the nearest one: `fd` cell 4 is that caption, and the figure leaves `fg`
        // (it goes in before its caption, `rf-flush-anchor`).
        int n = Model.NodeCount(on);
        int i = 1;
        int @out = 1;
        int row = 0;
        int c = 0;
        int r = 0;
        int p = 0;
        int gap = 0;
        int best = -1;
        int bestgap = 1000000;
        while (i < emon.Port.CellsLen(fg)) {
            row = emon.Port.CellsAt(fg, i);
            best = -1;
            bestgap = 1000000;
            c = 0;
            while (c < n) {
                if (((Model.NodeKind(on, c) == Model.NkCaption()) && (Model.NodeAux(on, c) == 1)) || ((Asset.AsGet(cand, row, 30) == 4) && ((Model.NodeKind(on, c) == Model.NkHeading()) && (Model.NodeAttr(on, oa, c, Model.FkNumber()) >= 0)))) {
                    p = Model.NodeParent(on, c);
                    r = Model.NodeRegionHead(on, c);
                    if ((p >= 0) && (r >= 0)) {
                        if (((Model.NodeKind(on, p) == Model.NkDocument()) || (Model.NodeKind(on, p) == Model.NkSection())) && ((Model.RegionPage(orr, r) == Asset.AsGet(cand, row, 0)) && ((RfMin(Model.RegionX1(orr, r), Asset.AsGet(cand, row, 7)) > RfMax(Model.RegionX0(orr, r), Asset.AsGet(cand, row, 5))) && (1 == 1)))) {
                            gap = Model.RegionY0(orr, r) - Asset.AsGet(cand, row, 8);
                            if ((gap >= -200) && ((gap <= RfCapgap) && (gap < bestgap))) {
                                best = c;
                                bestgap = gap;
                            }
                        }
                    }
                }
                c += 1;
            }
            if (best >= 0) {
                emon.Port.CellsSet(fd, (row * RfFd) + 4, best);
            } else {
                emon.Port.CellsSet(fg, @out, row);
                @out += 1;
            }
            i += 1;
        }
        emon.Port.CellsDrop(fg, @out);
        return 0;
    }
    internal static int RfChildren(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells nm, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab, int p, int np, int flush, int lpage, int ly) {
        // Copy the children of old node p under new node np; when `flush` is 1 the pending figures above each child go in
        // before it, and those above (lpage, ly) after the last (a section ends where its next sibling begins). A paragraph
        // that labels a figure (`ab`) is not copied.
        int c = Model.NodeFirstChild(on, p);
        int r = 0;
        int r2 = 0;
        int pg2 = 0;
        int y2 = 0;
        int bp = 0;
        int nn = 0;
        int caption = 0;
        int ri = 0;
        while (c >= 0) {
            if ((emon.Port.CellsLen(ab) == 0) || (emon.Port.CellsAt(ab, c) < 0)) {
                if ((flush == 1) && (Model.NodeKind(on, c) == Model.NkBreak())) {
                    bp = Model.NodeAttrIntOr(on, oa, c, Model.FkPage(), 0);
                    RfFlush(on, ab, cand, fg, fd, nodes, attrs, regions, np, bp, 0);
                }
                if (flush == 1) {
                    r = RfRegion(on, c);
                    if (r >= 0) {
                        RfFlush(on, ab, cand, fg, fd, nodes, attrs, regions, np, Model.RegionPage(orr, r), Model.RegionY0(orr, r));
                    }
                }
                caption = 0;
                ri = 0;
                while (ri < (emon.Port.CellsLen(fd) / RfFd)) {
                    if ((emon.Port.CellsAt(fd, (ri * RfFd) + 4) == c) && (Asset.AsGet(cand, ri, 30) == 4)) {
                        caption = 1;
                    }
                    ri += 1;
                }
                if ((flush == 1) && ((emon.Port.CellsLen(fd) > 0) && ((Model.NodeKind(on, c) == Model.NkCaption()) || (caption == 1)))) {
                    RfFlushAnchor(on, ab, cand, fd, nodes, attrs, regions, np, c);
                }
                nn = RfNode(on, oa, orr, nodes, attrs, regions, nm, c, np, caption);
                if (nn >= 0) {
                    if ((flush == 1) && (Model.NodeKind(on, c) == Model.NkSection())) {
                        r2 = RfNextRegion(on, c);
                        if (r2 >= 0) {
                            pg2 = Model.RegionPage(orr, r2);
                            y2 = Model.RegionY0(orr, r2);
                            RfChildren(on, oa, orr, nodes, attrs, regions, nm, cand, fg, fd, ab, c, nn, 1, pg2, y2);
                        } else {
                            RfChildren(on, oa, orr, nodes, attrs, regions, nm, cand, fg, fd, ab, c, nn, 1, lpage, ly);
                        }
                    } else {
                        RfChildren(on, oa, orr, nodes, attrs, regions, nm, cand, fg, fd, ab, c, nn, 0, lpage, ly);
                    }
                }
            }
            c = Model.NodeNext(on, c);
        }
        if (flush == 1) {
            RfFlush(on, ab, cand, fg, fd, nodes, attrs, regions, np, lpage, ly);
        }
        return 0;
    }
    public static int RsFigures(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells nm, emon.Port.Cells cand, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab) {
        // Copy the old Model's trees into the empty arenas `nodes`, `attrs`, `regions` (the text is shared), with the
        // figures `fg` (rows of `cand`, sorted: `as-figure-rows`; what they are: `fd`) placed among the document's and the
        // sections' blocks, and the paragraphs that label them left out. `nm` and `ab` are scratch (old node to new; old node to
        // the figure it labels). The caller swaps the arenas, then runs `rs-run`. Answers the new node count.
        int n = Model.NodeCount(on);
        int r = 0;
        int i = 0;
        int nr = 0;
        emon.Port.CellsDrop(nodes, 0);
        emon.Port.CellsDrop(attrs, 0);
        emon.Port.CellsDrop(regions, 0);
        emon.Port.CellsDrop(nm, 0);
        emon.Port.CellsDrop(ab, 0);
        while (i < n) {
            emon.Port.CellsPush(nm, -1);
            if (emon.Port.CellsLen(fd) > 0) {
                emon.Port.CellsPush(ab, -1);
            }
            i += 1;
        }
        if (emon.Port.CellsLen(fd) > 0) {
            RfGrow(on, orr, text, cand, fg, fd, ab, n);
            r = 0;
            while (r < n) {
                if ((Model.NodeParent(on, r) < 0) && (Model.NodeKind(on, r) == Model.NkDocument())) {
                    RfAbsorb(on, orr, text, cand, fg, fd, ab, r);
                }
                r += 1;
            }
            RfAnchor(on, oa, orr, cand, fg, fd);
            r = 0;
        }
        while (r < n) {
            if (Model.NodeParent(on, r) < 0) {
                nr = RfNode(on, oa, orr, nodes, attrs, regions, nm, r, -1, 0);
                if (nr >= 0) {
                    if (Model.NodeKind(on, r) == Model.NkDocument()) {
                        RfChildren(on, oa, orr, nodes, attrs, regions, nm, cand, fg, fd, ab, r, nr, 1, -1, -1);
                    } else {
                        RfChildren(on, oa, orr, nodes, attrs, regions, nm, cand, fg, fd, ab, r, nr, 0, -1, -1);
                    }
                }
            }
            r += 1;
        }
        RsRemap(attrs, nm);
        return Model.NodeCount(nodes);
    }
}
